Boolean dei_prk_init( void )
{
    Tsk tsk ;
    
    dei_prk_pip = os_pip_create( DEI_PRK_PIP_SIZE ) ; 
    
    dei_prk_irq = os_irq_create( );
       
    sys_timer_register ((Timer_Timer_Func)dei_prk_tmr , 1);

    tsk = os_tsk_create ( dei_prk_tsk , TASK_DEI_PRK_PRI , DEI_PRK_STACK , 0 , TASK_DEI_PRK_NAME ) ;
	
    os_tsk_start (tsk , 0) ;
    
    return TRUE ; 
}

